  font-size: 20px;
  font-weight: 700;
  line-height: 1.3;
}
@media (min-width: 768px) and (max-width: 991px) {
  .users-table-card__heading h2 {
    font-size: 18px;
  }
}
@media (max-width: 767px) {
  .users-table-card__heading h2 {
    font-size: 17px;
  }
}
.users-table-card__heading p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
@media (max-width: 767px) {
  .users-table-card__heading p {
    font-size: 14px;
  }
}

.users-table-card__tools {
  flex-shrink: 0;
}
@media (max-width: 767px) {
  .users-table-card__tools {
