  }
}

/*================================*
* Status
*=================================*/
.user-details-status {
  min-height: 28px;
  padding: 6px 10px;
  border-radius: 20px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
}
.user-details-status > span {
  width: 6px;
  height: 6px;
