  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
@media (max-width: 767px) {
  .user-details-page__actions {
    width: 100%;
  }
}

.user-details-back-btn,
.user-details-edit-btn {
  min-height: 42px;
  padding: 0 15px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  text-decoration: none;
  transition: border-color 0.2s ease, background-color 0.2s ease, color 0.2s ease;
}
.user-details-back-btn i,
.user-details-edit-btn i {
  font-size: 16px;
}
@media (max-width: 767px) {
  .user-details-back-btn,
  .user-details-edit-btn {
    flex: 1;
  }
}

.user-details-back-btn {
  border: 1px solid #ddd;
  background: #fff;
  color: #0D2B5A;
}
.user-details-back-btn:hover {
  border-color: #177245;
  color: #177245;
}

.user-details-edit-btn {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
}
.user-details-edit-btn:hover {
  border-color: rgba(23, 114, 69, 0.7);
  background: rgba(23, 114, 69, 0.7);
  color: #fff;
}

/*================================*
* Summary
*=================================*/
.user-details-summary {
  min-height: 60px;
  margin-bottom: 20px;
  padding: 11px 17px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 9px;
  background: #fff;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.025);
}
@media (min-width: 768px) and (max-width: 991px) {
  .user-details-summary {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
}
@media (max-width: 767px) {
  .user-details-summary {
    grid-template-columns: 1fr;
    padding: 14px;
    gap: 11px;
  }
}

.user-details-summary__item {
  padding: 3px 16px;
  border-right: 1px solid rgba(16, 26, 35, 0.07);
}
.user-details-summary__item:last-child {
  border-right: 0;
}
.user-details-summary__item span {
  display: block;
  margin-bottom: 4px;
  color: #555555;
  font-size: 14px;
  line-height: 1.35;
}
.user-details-summary__item strong {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
}
.user-details-summary__item .is-active {
  color: #198754;
}
.user-details-summary__item .is-inactive {
  color: #dc3545;
}
@media (min-width: 768px) and (max-width: 991px) {
  .user-details-summary__item:nth-child(2) {
    border-right: 0;
  }
  .user-details-summary__item:nth-child(-n+2) {
    padding-bottom: 8px;
    border-bottom: 1px solid rgba(16, 26, 35, 0.06);
  }
}
@media (max-width: 767px) {
  .user-details-summary__item {
    padding: 0 0 10px !important;
    border-right: 0 !important;
    border-bottom: 1px solid rgba(16, 26, 35, 0.06) !important;
  }
  .user-details-summary__item:last-child {
    padding-bottom: 0 !important;
    border-bottom: 0 !important;
  }
}

/*================================*
* Main Layout
*=================================*/
.user-details-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 20px;
  align-items: start;
}
@media (min-width: 1200px) and (max-width: 1399px) {
  .user-details-layout {
    grid-template-columns: minmax(0, 1fr) 315px;
  }
}
@media (min-width: 992px) and (max-width: 1199px) {
