/* =========================================================
   Page Header
========================================================= */
.settings-header {
  margin-bottom: 24px;
}

.settings-header-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.settings-header-text h1 {
  margin: 0 0 6px;
