  line-height: 1.5;
}

/* =========================================================
   Header Actions
========================================================= */
.settings-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* =========================================================
   Theme Toggle
========================================================= */
.theme-toggle {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 12px;
  border: 1px solid #e1e5e9;
  border-radius: 8px;
  background: #fff;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}
.theme-toggle:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}
.theme-toggle .theme-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
}
.theme-toggle .dark-icon,
.theme-toggle .dark-text {
  display: none;
}

/* =========================================================
   Dark Mode Toggle State
========================================================= */
body.dark-mode .theme-toggle .light-icon,
body.dark-mode .theme-toggle .light-text {
  display: none;
}
body.dark-mode .theme-toggle .dark-icon,
body.dark-mode .theme-toggle .dark-text {
  display: inline-flex;
}

/* =========================================================
   Language Dropdown
========================================================= */
.language-dropdown {
  position: relative;
}

.language-toggle {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 11px;
  border: 1px solid #e1e5e9;
  border-radius: 8px;
  background: #fff;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}
.language-toggle:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}
.language-toggle i:first-child {
  font-size: 16px;
}
.language-toggle i:last-child {
  font-size: 16px;
}

.language-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 50;
  width: 170px;
  padding: 6px;
  border: 1px solid #e7eaed;
  border-radius: 9px;
  background: #fff;
  box-shadow: 0 10px 30px rgba(16, 26, 35, 0.1);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-5px);
  transition: opacity 0.2s ease, visibility 0.2s ease, transform 0.2s ease;
}
.language-menu.show {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.language-option {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 10px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #555555;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
  transition: all 0.2s ease;
}
.language-option i {
  display: none;
  color: #177245;
  font-size: 16px;
}
.language-option:hover {
  background: rgba(23, 114, 69, 0.06);
  color: #177245;
}
.language-option.active {
  color: #177245;
  background: rgba(23, 114, 69, 0.07);
}
.language-option.active i {
  display: inline-flex;
}

/* =========================================================
   Settings Card
========================================================= */
.settings-card {
  margin-bottom: 20px;
  overflow: hidden;
  border: 1px solid #e8ebef;
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 4px 18px rgba(16, 26, 35, 0.04);
}

.settings-card-header {
  padding: 20px 22px;
  border-bottom: 1px solid #edf0f3;
}

.settings-card-heading {
  display: flex;
  align-items: center;
  gap: 13px;
}

.settings-card-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 19px;
}

.settings-card-header h2 {
  margin: 0 0 3px;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.4;
  font-weight: 700;
}
.settings-card-header p {
  margin: 0;
  color: #7b838b;
  font-size: 14px;
  line-height: 1.5;
}

.settings-card-body {
  padding: 22px;
}

/* =========================================================
   Form Grid
========================================================= */
.settings-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.form-group {
  min-width: 0;
}
.form-group.full-width {
  grid-column: 1/-1;
}
.form-group label {
  display: block;
  margin-bottom: 8px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}

.form-control {
  width: 100%;
  min-height: 46px;
  padding: 10px 13px;
  border: 1px solid #dfe3e8;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #101a23;
  font-size: 14px;
  line-height: 1.5;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.form-control::placeholder {
  color: #a0a7ae;
}
.form-control:hover {
  border-color: #cbd0d6;
}
.form-control:focus {
  border-color: #177245;
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.08);
}

textarea.form-control {
  min-height: 100px;
  resize: vertical;
}

select.form-control {
  cursor: pointer;
}

/* =========================================================
   Branding
========================================================= */
.branding-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.branding-item > label {
  display: block;
  margin-bottom: 8px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.upload-box {
  display: flex;
  align-items: center;
  gap: 15px;
  min-height: 120px;
  padding: 15px;
  border: 1px dashed #d8dde2;
  border-radius: 10px;
  background: #fafbfc;
}

.upload-preview {
  width: 88px;
  height: 88px;
  flex: 0 0 88px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border: 1px solid #e5e8eb;
  border-radius: 8px;
  background: #fff;
}
.upload-preview img {
  display: block;
  max-width: 80%;
  max-height: 80%;
  object-fit: contain;
}
.upload-preview.favicon-preview {
  width: 70px;
  height: 70px;
  flex-basis: 70px;
}

.upload-content {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}
.upload-content strong {
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.upload-content span {
  margin-bottom: 8px;
  color: #8a9198;
  font-size: 14px;
}

.upload-button {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 11px;
  border: 1px solid rgba(23, 114, 69, 0.18);
  border-radius: 7px;
  background: rgba(23, 114, 69, 0.06);
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}
.upload-button:hover {
  background: rgba(23, 114, 69, 0.11);
  border-color: rgba(23, 114, 69, 0.3);
}

/* =========================================================
   System Preferences
========================================================= */
.preference-list {
  width: 100%;
}

.preference-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 16px 0;
}
.preference-item + .preference-item {
  border-top: 1px solid #edf0f3;
}

.preference-content {
  min-width: 0;
}
.preference-content h3 {
  margin: 0 0 4px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.preference-content p {
  margin: 0;
  color: #858c94;
  font-size: 14px;
  line-height: 1.5;
}

/* =========================================================
   Switch
========================================================= */
.switch {
  position: relative;
  width: 44px;
  height: 24px;
  flex: 0 0 44px;
  display: inline-block;
  cursor: pointer;
}
.switch input {
  width: 0;
  height: 0;
  opacity: 0;
}
.switch input:checked + .slider {
  background: #177245;
}
.switch input:checked + .slider::before {
  transform: translateX(20px);
}
.switch .slider {
  position: absolute;
  inset: 0;
  border-radius: 50px;
  background: #cfd4da;
  transition: background 0.2s ease;
}
.switch .slider::before {
  content: "";
  position: absolute;
  width: 18px;
  height: 18px;
  top: 3px;
  left: 3px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.16);
  transition: transform 0.2s ease;
}

/* =========================================================
   Action Buttons
========================================================= */
.settings-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 4px;
}

.cancel-button,
.save-button {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 9px 17px;
  border-radius: 8px;
  font-size: 14px;
  line-height: 1;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.cancel-button {
  border: 1px solid #e0e4e8;
  background: #fff;
  color: #646b73;
}
.cancel-button:hover {
  background: #f7f8f9;
  border-color: #d2d7dc;
}

.save-button {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
}
.save-button:hover {
  background: rgba(23, 114, 69, 0.05);
  border-color: rgba(23, 114, 69, 0.05);
}

/* =========================================================
   LG
========================================================= */
