/*================================*
* User Status
*=================================*/
.role-user-status {
  min-height: 30px;
  padding: 0 10px;
  border-radius: 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
  text-transform: capitalize;
}

.role-user-status--active {
  border: 1px solid rgba(25, 135, 84, 0.15);
  background: rgba(25, 135, 84, 0.07);
  color: #198754;
}

.role-user-status--inactive {
  border: 1px solid rgba(255, 193, 7, 0.15);
  background: rgba(255, 193, 7, 0.07);
  color: #ffc107;
}

.role-user-status--suspended {
  border: 1px solid rgba(220, 38, 38, 0.15);
  background: rgba(220, 38, 38, 0.06);
  color: #dc2626;
}

/*================================*
* User Date
*=================================*/
.role-user-date {
  color: rgba(85, 85, 85, 0.8);
  font-size: 14px;
}

/*================================*
* User View Button
*=================================*/
.role-user-view-btn {
  width: 34px;
  height: 34px;
  border: 1px solid rgba(16, 26, 35, 0.08);
  border-radius: 6px;
  background: #fff;
  color: #555555;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  text-decoration: none;
  transition: all 0.2s ease;
}
.role-user-view-btn:hover {
  border-color: #177245;
  background: rgba(23, 114, 69, 0.06);
  color: #177245;
}

/*================================*
* Empty State
*=================================*/
.role-details-empty {
  min-height: 230px;
  padding: 35px 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  text-align: center;
}

.role-details-empty__icon {
  width: 54px;
  height: 54px;
  margin-bottom: 14px;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.role-details-empty__icon i {
  font-size: 23px;
}

.role-details-empty h3 {
  margin: 0 0 7px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
}
.role-details-empty p {
  max-width: 400px;
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

.role-details-empty__action {
  min-height: 40px;
  margin-top: 14px;
  padding: 0 14px;
  border: 1px solid #177245;
  border-radius: 7px;
  background: #177245;
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.2s ease;
}
.role-details-empty__action i {
  font-size: 16px;
}
.role-details-empty__action:hover {
  border-color: rgba(23, 114, 69, 0.7);
  background: rgba(23, 114, 69, 0.7);
  color: #fff;
}

/*================================*
* XL
*=================================*/
@media (min-width: 1200px) and (max-width: 1399px) {
  .role-details-page__header {
    margin-bottom: 22px;
  }
  .role-details-card--identity {
    padding: 18px;
  }
  .role-details-stat {
    padding: 18px;
  }
  .role-details-card__header {
    padding: 17px 18px;
  }
  .role-details-information {
    padding: 6px 18px 18px;
  }
  .role-permissions-list {
    padding: 8px 18px 18px;
  }
  .role-details-permissions-footer {
    padding: 14px 18px;
  }
  .role-users-table th {
    padding: 13px 18px;
  }
  .role-users-table td {
    padding: 14px 18px;
  }
}
/*================================*
* LG
*=================================*/
@media (min-width: 992px) and (max-width: 1199px) {
  .role-details-overview {
    grid-template-columns: 1fr 1fr;
  }
  .role-details-card--identity {
    grid-column: 1/-1;
  }
  .role-details-grid {
    grid-template-columns: 1fr;
  }
}
/*================================*
* MD
*=================================*/
@media (min-width: 768px) and (max-width: 991px) {
  .role-details-page__header {
    margin-bottom: 20px;
  }
  .role-details-page__actions {
    width: 100%;
  }
  .role-details-secondary-btn,
  .role-details-permissions-btn,
  .role-details-primary-btn {
    flex: 1;
  }
  .role-details-card {
    border-radius: 10px;
  }
  .role-details-card__header {
    padding: 16px;
  }
  .role-details-information {
    padding: 6px 16px 16px;
  }
  .role-permissions-list {
    padding: 8px 16px 16px;
  }
  .role-details-permissions-footer {
    padding: 14px 16px;
  }
  .role-users-table th {
    padding: 13px 16px;
  }
  .role-users-table td {
    padding: 14px 16px;
  }
}
/*================================*
* XS
*=================================*/
@media (max-width: 767px) {
  .role-details-page__header {
    margin-bottom: 18px;
  }
  .role-details-page__heading .role-details-page__eyebrow {
    font-size: 14px;
  }
  .role-details-page__heading h1 {
    font-size: 24px;
  }
  .role-details-page__heading p {
    font-size: 14px;
  }
  .role-details-page__actions {
    width: 100%;
    flex-direction: column;
    gap: 8px;
  }
  .role-details-secondary-btn,
  .role-details-permissions-btn,
  .role-details-primary-btn {
    width: 100%;
    flex: none;
  }
  .role-details-overview {
    grid-template-columns: 1fr;
    gap: 10px;
  }
  .role-details-card--identity {
    grid-column: auto;
    padding: 16px;
  }
  .role-details-identity {
    gap: 11px;
  }
  .role-details-identity__icon {
    width: 46px;
    height: 46px;
    flex-basis: 46px;
  }
  .role-details-identity__icon i {
    font-size: 21px;
  }
  .role-details-identity__content h2 {
    font-size: 20px;
  }
  .role-details-identity__content code {
    font-size: 14px;
  }
  .role-details-stat {
    min-height: 94px;
    padding: 16px;
  }
  .role-details-stat__content span {
    font-size: 14px;
  }
  .role-details-stat__content strong {
    font-size: 20px;
  }
  .role-details-stat__content small {
    font-size: 14px;
  }
  .role-details-card__header {
    padding: 16px;
  }
  .role-details-card__header h2 {
    font-size: 20px;
  }
  .role-details-card__header p {
    font-size: 14px;
  }
  .role-details-information {
    padding: 5px 16px 16px;
  }
  .role-details-information__item {
    align-items: flex-start;
    flex-direction: column;
    gap: 7px;
  }
  .role-details-information__item > span,
  .role-details-information__item > strong,
  .role-details-information__item > code {
    font-size: 14px;
  }
  .role-details-information__item > strong {
    text-align: left;
  }
  .role-permissions-list {
    padding: 7px 16px 16px;
  }
  .role-permission-item {
    gap: 9px;
  }
  .role-permission-item__icon {
    width: 34px;
    height: 34px;
    flex-basis: 34px;
  }
  .role-permission-item__icon i {
    font-size: 16px;
  }
  .role-permission-item__content strong {
    font-size: 16px;
  }
  .role-permission-item__content code,
  .role-permission-item__content p,
  .role-permission-item__content small {
    font-size: 14px;
  }
  .role-details-permissions-footer {
    padding: 14px 16px;
    align-items: stretch;
    flex-direction: column;
  }
  .role-details-permissions-footer__info {
    align-items: flex-start;
    font-size: 14px;
  }
  .role-details-manage-permissions-btn {
    width: 100%;
  }
  .role-users-table {
    min-width: 720px;
  }
  .role-users-table th {
    padding: 12px 14px;
    font-size: 14px;
  }
  .role-users-table td {
    padding: 13px 14px;
    font-size: 14px;
  }
  .role-user-profile__avatar {
    width: 34px;
    height: 34px;
    flex-basis: 34px;
  }
  .role-user-profile__info strong {
    font-size: 14px;
  }
  .role-user-email,
  .role-user-date,
  .role-user-status {
    font-size: 14px;
  }
  .role-details-empty {
    min-height: 210px;
    padding: 30px 16px;
  }
  .role-details-empty h3 {
    font-size: 20px;
  }
  .role-details-empty p {
    font-size: 14px;
  }
}
/*================================*
* Role Permissions Page
*=================================*/
.role-permissions-page {
  width: 100%;
}

/*================================*
* Page Header
*=================================*/
.role-permissions-page__header {
  margin-bottom: 20px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
}
@media (min-width: 768px) and (max-width: 991px) {
  .role-permissions-page__header {
    align-items: flex-start;
  }
}
@media (max-width: 767px) {
  .role-permissions-page__header {
    flex-direction: column;
    align-items: stretch;
    gap: 14px;
  }
}

.role-permissions-page__eyebrow {
  display: inline-block;
  margin-bottom: 8px;
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.role-permissions-page__heading h1 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 24px;
  font-weight: 700;
  line-height: 1.25;
}
@media (min-width: 768px) and (max-width: 991px) {
  .role-permissions-page__heading h1 {
    font-size: 22px;
  }
}
@media (max-width: 767px) {
  .role-permissions-page__heading h1 {
    font-size: 20px;
  }
}
.role-permissions-page__heading p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*================================*
* Header Button
*=================================*/
.role-permissions-back-btn {
  min-height: 42px;
  padding: 0 15px;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #0D2B5A;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s ease;
}
.role-permissions-back-btn i {
  font-size: 16px;
}
.role-permissions-back-btn:hover {
  border-color: #177245;
  color: #177245;
}
@media (max-width: 767px) {
  .role-permissions-back-btn {
    width: 100%;
  }
}

/*================================*
* Role Information Card
*=================================*/
.role-permissions-role-card {
  margin-bottom: 18px;
  padding: 18px 20px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 10px;
  background: #fff;
  display: flex;
  align-items: center;
  gap: 14px;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.03);
}
@media (max-width: 767px) {
  .role-permissions-role-card {
    padding: 15px;
    flex-wrap: wrap;
  }
}

.role-permissions-role-card__icon {
  width: 48px;
  height: 48px;
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 48px;
}
.role-permissions-role-card__icon i {
  font-size: 20px;
}

.role-permissions-role-card__content {
  min-width: 0;
  flex: 1;
}
.role-permissions-role-card__content > span {
  display: block;
  margin-bottom: 3px;
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.06em;
}
.role-permissions-role-card__content h2 {
  margin: 0 0 3px;
  color: #0D2B5A;
  font-size: 18px;
  font-weight: 600;
  line-height: 1.35;
}
.role-permissions-role-card__content p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}

.role-permissions-role-card__stats {
  display: flex;
  align-items: center;
  gap: 25px;
}
.role-permissions-role-card__stats > div {
  text-align: right;
}
.role-permissions-role-card__stats > div strong {
  display: block;
  margin-bottom: 2px;
  color: #0D2B5A;
  font-size: 18px;
  font-weight: 600;
  line-height: 1.3;
}
.role-permissions-role-card__stats > div span {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.3;
}
@media (max-width: 767px) {
  .role-permissions-role-card__stats {
    width: 100%;
    padding-top: 12px;
    border-top: 1px solid rgba(16, 26, 35, 0.06);
    justify-content: flex-start;
    gap: 30px;
  }
  .role-permissions-role-card__stats > div {
    text-align: left;
  }
}

/*================================*
* Main Permission Card
*=================================*/
.role-permissions-card {
  overflow: hidden;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.035);
}

/*================================*
* Card Header
*=================================*/
.role-permissions-card__header {
  min-height: 68px;
  padding: 15px 20px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.07);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}
.role-permissions-card__header h2 {
  margin: 0 0 4px;
  color: #0D2B5A;
  font-size: 18px;
  font-weight: 600;
  line-height: 1.3;
}
.role-permissions-card__header p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.45;
}
@media (min-width: 768px) and (max-width: 991px) {
  .role-permissions-card__header {
    align-items: flex-start;
    flex-direction: column;
  }
}
@media (max-width: 767px) {
  .role-permissions-card__header {
    padding: 15px 16px;
  }
}

/*================================*
* Tools
*=================================*/
.role-permissions-card__tools {
  display: flex;
  align-items: center;
  gap: 7px;
}
@media (max-width: 767px) {
  .role-permissions-card__tools {
    width: 100%;
  }
}

.role-permissions-tool-btn {
  min-height: 36px;
  padding: 0 11px;
  border: 1px solid #ddd;
  border-radius: 6px;
  background: #fff;
  color: #0D2B5A;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: 0.2s ease;
}
.role-permissions-tool-btn i {
  font-size: 15px;
}
.role-permissions-tool-btn:hover {
  border-color: #177245;
  color: #177245;
  background: rgba(23, 114, 69, 0.025);
}
@media (max-width: 767px) {
  .role-permissions-tool-btn {
    flex: 1;
  }
}

/*================================*
* Permission List
*=================================*/
.role-permissions-list {
  padding: 18px 20px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
@media (min-width: 768px) and (max-width: 991px) {
  .role-permissions-list {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 767px) {
  .role-permissions-list {
    padding: 15px;
  }
}

/*================================*
* Permission Item
*=================================*/
.role-permission-item {
  position: relative;
  min-height: 76px;
  padding: 13px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 8px;
  background: #fff;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  cursor: pointer;
  transition: border-color 0.2s ease, background-color 0.2s ease, box-shadow 0.2s ease;
}
.role-permission-item:hover {
  border-color: rgba(23, 114, 69, 0.3);
  background: rgba(23, 114, 69, 0.015);
}
.role-permission-item input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.role-permission-item:has(input:checked) {
  border-color: rgba(23, 114, 69, 0.35);
  background: rgba(23, 114, 69, 0.035);
  box-shadow: 0 2px 8px rgba(23, 114, 69, 0.05);
}
@media (max-width: 767px) {
  .role-permission-item {
    padding: 12px;
  }
}

.role-permission-item__checkbox {
  width: 22px;
  height: 22px;
  margin-top: 1px;
  border: 1px solid #ddd;
  border-radius: 5px;
  background: #fff;
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 22px;
  transition: 0.2s ease;
}
.role-permission-item__checkbox i {
  opacity: 0;
  font-size: 14px;
  line-height: 1;
}

.role-permission-item:has(input:checked) .role-permission-item__checkbox {
  border-color: #177245;
  background: #177245;
}
.role-permission-item:has(input:checked) .role-permission-item__checkbox i {
  opacity: 1;
}

.role-permission-item__content {
  min-width: 0;
}
.role-permission-item__content strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
}
.role-permission-item__content > span {
  display: block;
  margin-bottom: 4px;
  color: #177245;
  font-size: 14px;
  line-height: 1.35;
  word-break: break-word;
}
.role-permission-item__content small {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.45;
}

/*================================*
* Empty State
*=================================*/
.role-permissions-empty {
  grid-column: 1/-1;
  padding: 45px 20px;
  text-align: center;
}

.role-permissions-empty__icon {
  width: 52px;
  height: 52px;
  margin: 0 auto 12px;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  display: flex;
  align-items: center;
  justify-content: center;
}
.role-permissions-empty__icon i {
  font-size: 22px;
}

.role-permissions-empty h3 {
  margin: 0 0 6px;
  color: #0D2B5A;
  font-size: 18px;
  font-weight: 600;
}
.role-permissions-empty p {
  max-width: 450px;
  margin: 0 auto 16px;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

.role-permissions-empty__btn {
  min-height: 40px;
  padding: 0 14px;
  border-radius: 7px;
  background: #177245;
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s ease;
}
.role-permissions-empty__btn i {
  font-size: 16px;
}
.role-permissions-empty__btn:hover {
  background: rgba(23, 114, 69, 0.7);
  color: #fff;
}

/*================================*
* Card Footer
*=================================*/
.role-permissions-card__footer {
  min-height: 66px;
  padding: 12px 20px;
  border-top: 1px solid rgba(16, 26, 35, 0.07);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}
@media (max-width: 767px) {
  .role-permissions-card__footer {
    padding: 14px 15px;
    align-items: stretch;
    flex-direction: column;
  }
}

.role-permissions-selected {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #555555;
  font-size: 14px;
}
.role-permissions-selected i {
  color: #177245;
  font-size: 16px;
}
.role-permissions-selected strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

/*================================*
* Form Actions
*=================================*/
.role-permissions-form-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
@media (max-width: 767px) {
  .role-permissions-form-actions {
    width: 100%;
  }
}

.role-permissions-cancel-btn,
.role-permissions-save-btn {
  min-height: 40px;
  padding: 0 14px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s ease;
}
.role-permissions-cancel-btn i,
.role-permissions-save-btn i {
  font-size: 16px;
}
@media (max-width: 767px) {
  .role-permissions-cancel-btn,
  .role-permissions-save-btn {
    flex: 1;
  }
}

.role-permissions-cancel-btn {
  border: 1px solid #ddd;
  background: #fff;
  color: #0D2B5A;
}
.role-permissions-cancel-btn:hover {
  border-color: #177245;
  color: #177245;
}

.role-permissions-save-btn {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
  cursor: pointer;
}
.role-permissions-save-btn:hover {
  border-color: rgba(23, 114, 69, 0.7);
  background: rgba(23, 114, 69, 0.7);
}

/*================================*
* Responsive
*=================================*/
