/*==========================================================================
| ADD PAYMENT MODAL
| IMPORTANT: Modal is OUTSIDE .customer-account-payments-page
===========================================================================*/
.customer-account-payment-modal {
  position: fixed;
  inset: 0;
  z-index: 99999;
  display: none;
  width: 100%;
  height: 100%;
}
.customer-account-payment-modal.active {
  display: block;
}
.customer-account-payment-modal {
  /*
  |--------------------------------------------------------------------------
  | Overlay
  |--------------------------------------------------------------------------
  */
}
.customer-account-payment-modal__overlay {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  background: rgba(10, 25, 20, 0.48);
  backdrop-filter: blur(3px);
}
.customer-account-payment-modal {
  /*
  |--------------------------------------------------------------------------
  | Modal Content
  |--------------------------------------------------------------------------
  */
}
.customer-account-payment-modal__content {
  position: relative;
  z-index: 2;
  width: calc(100% - 30px);
  max-width: 500px;
  max-height: calc(100vh - 30px);
  overflow-y: auto;
  margin: 15px auto;
  border: 1px solid #ddd;
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.18);
  animation: paymentModalIn 0.2s ease forwards;
}
.customer-account-payment-modal {
  /*
  |--------------------------------------------------------------------------
  | Header
  |--------------------------------------------------------------------------
  */
}
.customer-account-payment-modal__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  padding: 18px 20px;
  border-bottom: 1px solid #ddd;
}
.customer-account-payment-modal__header span {
  display: block;
  margin-bottom: 4px;
  color: #177245;
  font-size: 14px;
  line-height: 1.2;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.customer-account-payment-modal__header h2 {
  margin: 0 !important;
  color: #0D2B5A !important;
  font-family: "Poppins", sans-serif !important;
  font-size: 22px !important;
  line-height: 1.25 !important;
  font-weight: 700 !important;
}
.customer-account-payment-modal {
  /*
  |--------------------------------------------------------------------------
  | Close
  |--------------------------------------------------------------------------
  */
}
.customer-account-payment-modal__close {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #666;
  font-size: 18px;
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}
.customer-account-payment-modal__close:hover {
  border-color: #177245;
  background: rgba(15, 61, 46, 0.05);
  color: #177245;
}
.customer-account-payment-modal {
  /*
  |--------------------------------------------------------------------------
  | Form
  |--------------------------------------------------------------------------
  */
}
.customer-account-payment-modal__form {
  display: block;
  padding: 20px;
}
.customer-account-payment-modal {
  /*
  |--------------------------------------------------------------------------
  | Actions
  |--------------------------------------------------------------------------
  */
}
.customer-account-payment-modal__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid #ddd;
}

/*
|--------------------------------------------------------------------------
| Modal Form Groups
|--------------------------------------------------------------------------
*/
.customer-account-payment-modal .modal-form-group {
  margin: 0 0 15px;
}
.customer-account-payment-modal .modal-form-group label {
  display: block;
  margin: 0 0 6px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  line-height: 1.3;
  font-weight: 600;
}
.customer-account-payment-modal .modal-form-group input {
  display: block;
  width: 100%;
  height: 43px;
  margin: 0;
  padding: 0 12px;
  border: 1px solid #d9d9d9;
  border-radius: 7px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  line-height: 43px;
  box-sizing: border-box;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.customer-account-payment-modal .modal-form-group input::placeholder {
  color: #aaa;
  opacity: 1;
}
.customer-account-payment-modal .modal-form-group input:focus {
  border-color: rgba(15, 61, 46, 0.45);
  box-shadow: 0 0 0 3px rgba(15, 61, 46, 0.06);
}
.customer-account-payment-modal {
  /*
  |--------------------------------------------------------------------------
  | Two Column Inputs
  |--------------------------------------------------------------------------
  */
}
.customer-account-payment-modal .modal-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.customer-account-payment-modal {
  /*
  |--------------------------------------------------------------------------
  | Checkbox
  |--------------------------------------------------------------------------
  */
}
.customer-account-payment-modal .modal-checkbox {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 2px 0 0;
  color: #777;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  line-height: 1.4;
  cursor: pointer;
}
.customer-account-payment-modal .modal-checkbox input {
  width: 15px;
  height: 15px;
  flex: 0 0 15px;
  margin: 0;
  padding: 0;
  accent-color: #177245;
  cursor: pointer;
}
.customer-account-payment-modal .modal-checkbox span {
  color: #777;
  font-size: 14px;
}
.customer-account-payment-modal {
  /*
  |--------------------------------------------------------------------------
  | Buttons
  |--------------------------------------------------------------------------
  */
}
.customer-account-payment-modal .modal-cancel-btn,
.customer-account-payment-modal .modal-save-btn {
  min-height: 41px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin: 0;
  padding: 0 15px;
  border-radius: 7px;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  line-height: 1;
  font-weight: 600;
  cursor: pointer;
  box-sizing: border-box;
  transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}
.customer-account-payment-modal .modal-cancel-btn {
  border: 1px solid #ddd;
  background: #fff;
  color: #666;
}
.customer-account-payment-modal .modal-cancel-btn:hover {
  border-color: #ccc;
  background: #f8f8f8;
  color: #0D2B5A;
}
.customer-account-payment-modal .modal-save-btn {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
}
.customer-account-payment-modal .modal-save-btn:hover {
  opacity: 0.92;
}
.customer-account-payment-modal .modal-save-btn i {
  font-size: 15px;
}

/*
|--------------------------------------------------------------------------
| Body Lock
|--------------------------------------------------------------------------
*/
body.payment-modal-open {
  overflow: hidden;
}

/*
|--------------------------------------------------------------------------
| Modal Animation
|--------------------------------------------------------------------------
*/
@keyframes paymentModalIn {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
