/*==================================================
| Layout
==================================================*/
.smart-buy-purchase-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
  align-items: start;
  gap: 15px;
}

.smart-buy-purchase-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.smart-buy-purchase-sidebar {
  min-width: 0;
  position: sticky;
  top: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

/*==================================================
| Card
==================================================*/
.smart-buy-purchase-card {
  overflow: hidden;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.025);
}

.smart-buy-purchase-card__header {
  min-height: 58px;
  padding: 12px 16px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.06);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.smart-buy-purchase-card__header h2 {
  margin: 0 0 3px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 18px;
  font-weight: 600;
}

.smart-buy-purchase-card__header p {
  margin: 0;
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-purchase-card__body {
  padding: 16px;
}

/*==================================================
| Product
==================================================*/
.smart-buy-purchase-product {
  padding: 17px;
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.smart-buy-purchase-product__icon {
  width: 64px;
  height: 64px;
  flex: 0 0 64px;
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.07);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.smart-buy-purchase-product__icon i {
  font-size: 26px;
}

.smart-buy-purchase-product__content {
  min-width: 0;
}

.smart-buy-purchase-product__content > span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-purchase-product__content h3 {
  margin: 2px 0 5px;
  color: #0D2B5A;
  font-size: 18px;
  font-weight: 600;
}

.smart-buy-purchase-product__content > p {
  margin: 0 0 12px;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

.smart-buy-purchase-product__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.smart-buy-purchase-product__meta > div {
  min-width: 110px;
  padding: 7px 9px;
  border: 1px solid rgba(16, 26, 35, 0.055);
  border-radius: 7px;
  background: #fafbfc;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.smart-buy-purchase-product__meta span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-purchase-product__meta strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

/*==================================================
| Grid
==================================================*/
.smart-buy-purchase-grid {
  display: grid;
  gap: 12px;
  margin-bottom: 13px;
}

.smart-buy-purchase-grid--two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.smart-buy-purchase-grid--three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

/*==================================================
| Fields
==================================================*/
.smart-buy-purchase-field {
  margin-bottom: 13px;
}

.smart-buy-purchase-grid .smart-buy-purchase-field {
  margin-bottom: 0;
}

.smart-buy-purchase-field:last-child {
  margin-bottom: 0;
}

.smart-buy-purchase-field label {
  display: block;
  margin-bottom: 5px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.smart-buy-purchase-field label span {
  color: #d45c5c;
}

.smart-buy-purchase-field input,
.smart-buy-purchase-field select,
.smart-buy-purchase-field textarea {
  width: 100%;
  border: 1px solid rgba(16, 26, 35, 0.1);
  border-radius: 7px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.smart-buy-purchase-field input,
.smart-buy-purchase-field select {
  height: 39px;
  padding: 0 10px;
}

.smart-buy-purchase-field textarea {
  min-height: 105px;
  padding: 9px 10px;
  resize: vertical;
  line-height: 1.5;
}

.smart-buy-purchase-field input:focus,
.smart-buy-purchase-field select:focus,
.smart-buy-purchase-field textarea:focus {
  border-color: rgba(23, 114, 69, 0.35);
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.06);
}

/*==================================================
| Money
==================================================*/
.smart-buy-purchase-money {
  position: relative;
}

.smart-buy-purchase-money > span {
  position: absolute;
  top: 50%;
  left: 10px;
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
  font-weight: 600;
  transform: translateY(-50%);
  pointer-events: none;
}

.smart-buy-purchase-money input {
  padding-left: 26px !important;
}

/*==================================================
| Footer
==================================================*/
.smart-buy-purchase-field-footer {
  margin-top: 4px;
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.smart-buy-purchase-field-footer span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

/*==================================================
| Upload
==================================================*/
.smart-buy-purchase-upload {
  min-height: 150px;
  padding: 20px;
  border: 1px dashed rgba(16, 26, 35, 0.16);
  border-radius: 9px;
  background: #fafbfc;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 6px;
  text-align: center;
  cursor: pointer;
  transition: border-color 0.2s ease, background-color 0.2s ease;
}

.smart-buy-purchase-upload:hover {
  border-color: rgba(23, 114, 69, 0.3);
  background: rgba(23, 114, 69, 0.025);
}

.smart-buy-purchase-upload input {
  display: none;
}

.smart-buy-purchase-upload__icon {
  width: 40px;
  height: 40px;
  margin-bottom: 3px;
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.smart-buy-purchase-upload__icon i {
  font-size: 20px;
}

.smart-buy-purchase-upload strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.smart-buy-purchase-upload > span:last-child {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

/*==================================================
| Files
==================================================*/
.smart-buy-purchase-file-list {
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.smart-buy-purchase-file {
  min-height: 40px;
  padding: 6px 8px;
  border: 1px solid rgba(16, 26, 35, 0.06);
  border-radius: 7px;
  display: flex;
  align-items: center;
  gap: 7px;
}

.smart-buy-purchase-file__icon {
  width: 28px;
  height: 28px;
  border-radius: 6px;
  background: #f5f6f7;
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.smart-buy-purchase-file__name {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  color: #0D2B5A;
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.smart-buy-purchase-file__size {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
  white-space: nowrap;
}

/*==================================================
| Status Note
==================================================*/
.smart-buy-purchase-status-note {
  margin-top: 10px;
  padding: 9px;
  border-radius: 7px;
  background: #f7f9fa;
  display: flex;
  align-items: flex-start;
  gap: 7px;
}

.smart-buy-purchase-status-note i {
  color: #177245;
  font-size: 15px;
}

.smart-buy-purchase-status-note p {
  margin: 0;
  color: rgba(85, 85, 85, 0.8);
  font-size: 14px;
  line-height: 1.45;
}

/*==================================================
| Payment
==================================================*/
.smart-buy-purchase-payment {
  padding: 13px 15px;
}

.smart-buy-purchase-payment__status {
  display: flex;
  align-items: center;
  gap: 8px;
}

.smart-buy-purchase-payment__status > span {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #eaf7ef;
  color: #2d8752;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.smart-buy-purchase-payment__status > span i {
  font-size: 17px;
}

.smart-buy-purchase-payment__status > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.smart-buy-purchase-payment__status strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.smart-buy-purchase-payment__status small {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-purchase-payment__total {
  margin-top: 12px;
  padding-top: 11px;
  border-top: 1px solid rgba(16, 26, 35, 0.055);
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.smart-buy-purchase-payment__total span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-purchase-payment__total strong {
  color: #177245;
  font-size: 18px;
}

/*==================================================
| Summary
==================================================*/
.smart-buy-purchase-summary {
  padding: 5px 15px 8px;
}

.smart-buy-purchase-summary > div {
  min-height: 42px;
  padding: 7px 0;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.smart-buy-purchase-summary > div:last-child {
  border-bottom: 0;
}

.smart-buy-purchase-summary span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-purchase-summary strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.smart-buy-purchase-summary > div:last-child strong {
  color: #177245;
  font-size: 18px;
}

/*==================================================
| Customer
==================================================*/
.smart-buy-purchase-customer {
  padding: 13px 15px;
  display: flex;
  align-items: center;
  gap: 9px;
}

.smart-buy-purchase-customer__avatar {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
}

.smart-buy-purchase-customer > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.smart-buy-purchase-customer strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.smart-buy-purchase-customer span {
  overflow: hidden;
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/*==================================================
| Destination
==================================================*/
.smart-buy-purchase-destination {
  padding: 10px 15px 13px;
  border-top: 1px solid rgba(16, 26, 35, 0.055);
  display: flex;
  align-items: flex-start;
  gap: 7px;
}

.smart-buy-purchase-destination > i {
  color: #177245;
  font-size: 16px;
}

.smart-buy-purchase-destination > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.smart-buy-purchase-destination span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-purchase-destination strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

/*==================================================
| Next
==================================================*/
.smart-buy-purchase-next {
  padding: 12px;
  border: 1px solid rgba(23, 114, 69, 0.15);
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.035);
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.smart-buy-purchase-next__icon {
  width: 29px;
  height: 29px;
  flex: 0 0 29px;
  border-radius: 7px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.smart-buy-purchase-next strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
}

.smart-buy-purchase-next p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.45;
}

/*==================================================
| Footer
==================================================*/
.smart-buy-purchase-footer {
  margin-top: 15px;
  padding: 12px 15px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 10px;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.025);
}

.smart-buy-purchase-footer > div:first-child {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.smart-buy-purchase-footer > div:first-child span {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.smart-buy-purchase-footer > div:first-child small {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-purchase-footer__actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

.smart-buy-purchase-cancel,
.smart-buy-purchase-confirm {
  min-height: 38px;
  padding: 0 12px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
}

.smart-buy-purchase-cancel {
  color: #555555;
}
.smart-buy-purchase-cancel:hover {
  background: #f7f8f9;
  color: #0D2B5A;
}

.smart-buy-purchase-confirm {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
  transition: 0.2s ease;
}
.smart-buy-purchase-confirm:hover {
  border-color: rgba(23, 114, 69, 0.07);
  background: rgba(23, 114, 69, 0.07);
}

.smart-buy-purchase-confirm:disabled {
  opacity: 0.65;
  cursor: wait;
}

/*==================================================
| Loading
==================================================*/
.smart-buy-purchase-spin {
  animation: smartBuyPurchaseSpin 0.8s linear infinite;
}

@keyframes smartBuyPurchaseSpin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
/*==================================================
| Responsive - LG
==================================================*/
@media (min-width: 992px) and (max-width: 1199px) {
  .smart-buy-purchase-layout {
    grid-template-columns: minmax(0, 1fr) 270px;
  }
}
/*==================================================
| Responsive - MD
==================================================*/
@media (min-width: 768px) and (max-width: 991px) {
  .smart-buy-purchase-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .smart-buy-purchase-layout {
    grid-template-columns: 1fr;
  }
  .smart-buy-purchase-sidebar {
    position: static;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .smart-buy-purchase-next {
    grid-column: 1/-1;
  }
}
/*==================================================
| Responsive - XS
==================================================*/
@media (max-width: 767px) {
  .smart-buy-purchase-heading h1 {
    font-size: 20px;
  }
  .smart-buy-purchase-heading__icon {
    width: 40px;
    height: 40px;
    flex-basis: 40px;
  }
  .smart-buy-purchase-grid--two,
  .smart-buy-purchase-grid--three {
    grid-template-columns: 1fr;
  }
  .smart-buy-purchase-product {
    padding: 14px;
    flex-direction: column;
  }
  .smart-buy-purchase-product__icon {
    width: 55px;
    height: 55px;
    flex-basis: 55px;
  }
  .smart-buy-purchase-card__body {
    padding: 13px;
  }
  .smart-buy-purchase-sidebar {
    grid-template-columns: 1fr;
  }
  .smart-buy-purchase-next {
    grid-column: auto;
  }
  .smart-buy-purchase-footer {
    align-items: stretch;
    flex-direction: column;
  }
  .smart-buy-purchase-footer__actions {
    width: 100%;
  }
  .smart-buy-purchase-cancel,
  .smart-buy-purchase-confirm {
    flex: 1;
  }
}
