  border: 1px solid #177245;
  background: #177245;
  color: #fff;
  transition: 0.2s ease;
}
.smart-buy-shipment-create:hover {
  border-color: rgba(23, 114, 69, 0.07);
  background: rgba(23, 114, 69, 0.07);
}

.smart-buy-shipment-create:disabled {
  opacity: 0.65;
  cursor: wait;
}

