  }
  .smart-buy-shipment-notice {
    grid-column: 1/-1;
  }
}
/*==================================================
| Responsive XS
==================================================*/
@media (max-width: 767px) {
  .smart-buy-shipment-heading h1 {
    font-size: 20px;
  }
  .smart-buy-shipment-heading__icon {
    width: 40px;
    height: 40px;
