  .smart-buy-shipment-notice {
    grid-column: auto;
  }
  .smart-buy-shipment-footer {
    align-items: stretch;
    flex-direction: column;
  }
  .smart-buy-shipment-footer__actions {
    width: 100%;
  }
  .smart-buy-shipment-cancel,
  .smart-buy-shipment-create {
    flex: 1;
  }
}
