}
.product-details-page__inventory-total span {
  color: #555555;
  font-size: 14px;
}
.product-details-page__inventory-total strong {
  color: #0D2B5A;
  font-size: 20px;
  font-weight: 600;
}
.product-details-page__inventory-list {
  display: flex;
  flex-direction: column;
  gap: 1px;
  margin-top: 12px;
  border: 1px solid #eaecf0;
  border-radius: 6px;
