}
.product-details-page__inventory-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 10px;
  background: #fff;
}
.product-details-page__inventory-item:not(:last-child) {
  border-bottom: 1px solid #eaecf0;
}
.product-details-page__inventory-item span {
  overflow: hidden;
  color: #555555;
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.product-details-page__inventory-item strong {
  flex-shrink: 0;
  color: #198754;
  font-size: 14px;
  font-weight: 600;
}
.product-details-page__inventory-item strong.is-low {
  color: #ffc107;
}
.product-details-page__inventory-item strong.is-out {
  color: #dc3545;
}
.product-details-page__inventory-more {
  margin-top: 10px;
  color: #555555;
  font-size: 14px;
  text-align: center;
}
.product-details-page__inventory-note {
  margin: 10px 0 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.product-details-page__timeline {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.product-details-page__timeline > div {
  position: relative;
  display: flex;
  gap: 11px;
}
.product-details-page__timeline > div:not(:last-child)::after {
  position: absolute;
  top: 13px;
  left: 5px;
  width: 1px;
  height: calc(100% + 18px);
  background: #eaecf0;
  content: "";
}
.product-details-page__timeline > div > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.product-details-page__timeline span:not(.product-details-page__timeline-dot) {
  color: #555555;
  font-size: 14px;
}
.product-details-page__timeline strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 500;
}
.product-details-page__timeline-dot {
  position: relative;
  z-index: 1;
  width: 11px;
  height: 11px;
  margin-top: 3px;
  flex-shrink: 0;
  border: 2px solid #177245;
  border-radius: 50%;
  background: #fff;
}
.product-details-page__actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.product-details-page__action {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  width: 100%;
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.2s ease;
}
.product-details-page__action i {
  font-size: 17px;
}
.product-details-page__action--primary {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.product-details-page__action--primary:hover {
  border-color: #D4AF37;
  background: #D4AF37;
  color: #fff;
}
.product-details-page__action--danger {
  border-color: rgba(220, 53, 69, 0.25);
  background: rgba(220, 53, 69, 0.05);
  color: #dc3545;
}
.product-details-page__action--danger:hover {
  border-color: #dc3545;
  background: #dc3545;
  color: #fff;
}
.product-details-page__lightbox {
  position: fixed;
  z-index: 9999;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 30px;
  visibility: hidden;
  opacity: 0;
  transition: opacity 0.2s ease, visibility 0.2s ease;
}
.product-details-page__lightbox.is-visible {
  visibility: visible;
  opacity: 1;
}
.product-details-page__lightbox-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.8);
  cursor: pointer;
}
.product-details-page__lightbox-content {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  width: min(900px, 90vw);
  height: min(700px, 85vh);
}
.product-details-page__lightbox-content img {
  display: block;
  max-width: 100%;
  max-height: 100%;
  border-radius: 6px;
  object-fit: contain;
}
.product-details-page__lightbox-close, .product-details-page__lightbox-nav {
  position: absolute;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border: 0;
  border-radius: 50%;
  background: #fff;
  color: #0D2B5A;
  cursor: pointer;
  transition: all 0.2s ease;
}
.product-details-page__lightbox-close i, .product-details-page__lightbox-nav i {
  font-size: 22px;
}
.product-details-page__lightbox-close:hover, .product-details-page__lightbox-nav:hover {
  background: #177245;
  color: #fff;
}
.product-details-page__lightbox-close {
  top: -18px;
  right: -18px;
}
.product-details-page__lightbox-nav {
  top: 50%;
  transform: translateY(-50%);
}
.product-details-page__lightbox-nav--prev {
  left: -65px;
}
.product-details-page__lightbox-nav--next {
  right: -65px;
}
@media (min-width: 1200px) and (max-width: 1399px) {
  .product-details-page__grid {
    grid-template-columns: minmax(0, 1fr) 320px;
  }
  .product-details-page__pricing-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (min-width: 992px) and (max-width: 1199px) {
  .product-details-page__title-row {
    flex-direction: column;
  }
  .product-details-page__header-actions {
    width: 100%;
  }
  .product-details-page__status-bar {
    align-items: flex-start;
    flex-direction: column;
  }
  .product-details-page__grid {
    grid-template-columns: 1fr;
  }
  .product-details-page__sidebar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .product-details-page__card--sticky {
    position: static;
  }
}
@media (min-width: 768px) and (max-width: 991px) {
  .product-details-page {
    padding: 18px 0 30px;
  }
  .product-details-page__overview {
    grid-template-columns: 1fr;
  }
  .product-details-page__thumbnail {
    width: 160px;
    height: 160px;
  }
  .product-details-page__sidebar {
    grid-template-columns: 1fr;
  }
  .product-details-page__variant {
    grid-template-columns: 56px minmax(0, 1fr);
  }
  .product-details-page__variant-price, .product-details-page__variant-stock {
    padding-top: 10px;
    border-top: 1px solid #eaecf0;
  }
  .product-details-page__variant-price {
    grid-column: 2;
  }
  .product-details-page__variant-stock {
    grid-column: 2;
  }
  .product-details-page__gallery {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .product-details-page__lightbox-nav--prev {
    left: 10px;
  }
  .product-details-page__lightbox-nav--next {
    right: 10px;
  }
  .product-details-page__lightbox-close {
    top: 10px;
    right: 10px;
  }
}
@media (min-width: 480px) and (max-width: 767px) {
  .product-details-page__title-row h1 {
    font-size: 22px;
  }
  .product-details-page__header-actions {
    flex-direction: column;
  }
  .product-details-page__button {
    width: 100%;
  }
  .product-details-page__card {
    padding: 16px;
  }
  .product-details-page__field-grid {
    grid-template-columns: 1fr;
  }
  .product-details-page__pricing-grid {
    grid-template-columns: 1fr;
  }
  .product-details-page__gallery {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .product-details-page__variant-top {
    align-items: flex-start;
    flex-direction: column;
  }
  .product-details-page__lightbox {
    padding: 15px;
  }
}
@media (max-width: 767px) {
  .product-details-page__meta {
    flex-direction: column;
    align-items: flex-start;
  }
  .product-details-page__overview {
    gap: 18px;
  }
  .product-details-page__thumbnail {
    width: 140px;
    height: 140px;
  }
  .product-details-page__variant {
    grid-template-columns: 48px minmax(0, 1fr);
    gap: 10px;
  }
  .product-details-page__variant-image {
    width: 48px;
    height: 48px;
  }
}

