.category-details-page__status-value {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.category-details-page__product-stat {
  display: flex;
  align-items: center;
  gap: 13px;
}
.category-details-page__product-stat-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 46px;
  width: 46px;
  height: 46px;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
}
.category-details-page__product-stat-icon i {
  font-size: 21px;
}
.category-details-page__product-stat > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.category-details-page__product-stat > div:last-child strong {
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 22px;
  font-weight: 600;
  line-height: 1.3;
}
.category-details-page__product-stat > div:last-child span {
  color: #555555;
  font-size: 14px;
}
.category-details-page__record {
  display: flex;
  flex-direction: column;
  gap: 15px;
}
.category-details-page__record > div {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  padding-bottom: 15px;
  border-bottom: 1px solid #eaecf0;
}
.category-details-page__record > div:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}
.category-details-page__record span {
  color: #555555;
  font-size: 14px;
}
.category-details-page__record strong {
  max-width: 60%;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  text-align: right;
}
.category-details-page__quick-actions {
  display: flex;
  flex-direction: column;
  gap: 9px;
}
.category-details-page__quick-action {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 44px;
  padding: 0 13px;
  border: 1px solid #eaecf0;
  border-radius: 7px;
  background: #fff;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
  -webkit-transition: all 0.3s linear 0s;
  -o-transition: all 0.3s linear 0s;
  transition: all 0.3s linear 0s;
}
.category-details-page__quick-action i {
  color: #177245;
  font-size: 18px;
}
.category-details-page__quick-action:hover, .category-details-page__quick-action.is-hovered {
  border-color: #177245;
  color: #177245;
}
.category-details-page__quick-action--edit {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.category-details-page__quick-action--edit i {
  color: #fff;
}
.category-details-page__quick-action--edit:hover, .category-details-page__quick-action--edit.is-hovered {
  border-color: #D4AF37;
  background: #D4AF37;
  color: #fff;
}
@media (min-width: 1200px) and (max-width: 1399px) {
  .category-details-page__layout {
    grid-template-columns: minmax(0, 1fr) 300px;
  }
}
@media (min-width: 992px) and (max-width: 1199px) {
  .category-details-page {
