/*
|--------------------------------------------------------------------------
| Form Grid
|--------------------------------------------------------------------------
*/
.brand-edit-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

/*
|--------------------------------------------------------------------------
| Form Field
|--------------------------------------------------------------------------
*/
.brand-edit-field {
  min-width: 0;
}
.brand-edit-field--full {
