}
.brand-edit-field label {
  display: block;
  margin-bottom: 7px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.brand-edit-field label span {
  color: #dc3545;
}
.brand-edit-field input,
.brand-edit-field textarea,
.brand-edit-field select {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid #ddd;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  line-height: 1.5;
