}
.brand-edit-field input::placeholder,
.brand-edit-field textarea::placeholder {
  color: #999;
}
.brand-edit-field input:focus,
.brand-edit-field textarea:focus,
.brand-edit-field select:focus {
  border-color: #177245;
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.07);
}
.brand-edit-field small {
  display: block;
  margin-top: 6px;
