/*
|--------------------------------------------------------------------------
| Settings
|--------------------------------------------------------------------------
*/
.brand-edit-settings {
  display: flex;
  flex-direction: column;
}

.brand-edit-setting {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 16px 0;
  border-bottom: 1px solid rgba(221, 221, 221, 0.7);
}
.brand-edit-setting:first-child {
  padding-top: 0;
}
.brand-edit-setting:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}
.brand-edit-setting__content {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.brand-edit-setting__icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.08);
