/*
|--------------------------------------------------------------------------
| Form Actions
|--------------------------------------------------------------------------
*/
.brand-edit-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding-top: 5px;
  margin-bottom: 20px;
}
.brand-edit-actions__cancel, .brand-edit-actions__submit {
  min-height: 43px;
  padding: 0 16px;
  border-radius: 8px;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: 0.2s;
}
.brand-edit-actions__cancel {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #ddd;
  background: #fff;
  color: #555555;
}
.brand-edit-actions__cancel:hover {
  border-color: rgba(23, 114, 69, 0.4);
  color: #177245;
}
.brand-edit-actions__submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
}
.brand-edit-actions__submit i {
  font-size: 17px;
}
.brand-edit-actions__submit:hover {
  opacity: 0.9;
}

/*
|--------------------------------------------------------------------------
| Responsive - LG
|--------------------------------------------------------------------------
*/
@media (min-width: 992px) and (max-width: 1199px) {
  .brand-edit-image-section {
    grid-template-columns: 240px minmax(0, 1fr);
  }
}
/*
|--------------------------------------------------------------------------
| Responsive - MD
|--------------------------------------------------------------------------
*/
@media (min-width: 768px) and (max-width: 991px) {
  .brand-edit-page__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .brand-edit-page__header-actions {
    width: 100%;
  }
  .brand-edit-page__back-btn {
    width: fit-content;
  }
  .brand-type-options {
    grid-template-columns: 1fr;
  }
  .brand-edit-grid {
    grid-template-columns: 1fr;
  }
  .brand-edit-field--full {
    grid-column: auto;
  }
  .brand-edit-image-section {
    grid-template-columns: 1fr;
  }
  .brand-edit-current-image {
    max-width: 300px;
  }
}
/*
|--------------------------------------------------------------------------
| Responsive - XS
|--------------------------------------------------------------------------
*/
@media (max-width: 767px) {
  .brand-edit-page__header h1 {
    font-size: 24px;
  }
  .brand-edit-card__header,
  .brand-edit-card__body {
    padding: 16px;
  }
  .brand-edit-setting {
    align-items: flex-start;
  }
  .brand-edit-setting__content {
    align-items: flex-start;
  }
  .brand-edit-upload {
    align-items: flex-start;
    flex-wrap: wrap;
  }
  .brand-edit-upload__content {
    flex: 1 1 calc(100% - 67px);
  }
  .brand-edit-upload__btn {
    width: 100%;
  }
  .brand-edit-actions {
    flex-direction: column-reverse;
  }
  .brand-edit-actions__cancel, .brand-edit-actions__submit {
    width: 100%;
  }
}
