.inventory-table th {
  padding: 12px 20px;
  border-bottom: 1px solid #e5e7eb;
  background: #f9fafb;
  color: #6b7280;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-align: left;
  text-transform: uppercase;
  white-space: nowrap;
}
.inventory-table td {
  padding: 15px 20px;
  border-bottom: 1px solid #f0f1f3;
  vertical-align: middle;
}
.inventory-table tbody tr:last-child td {
  border-bottom: 0;
}
.inventory-table__row {
  transition: background-color 0.15s ease;
}
.inventory-table__row:hover {
  background: #fafafa;
}
.inventory-table__action-column {
  width: 100px;
  text-align: right;
}
.inventory-table__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
}
.inventory-table__empty {
  padding: 60px 20px !important;
}

.inventory-product {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 240px;
}
.inventory-product__image {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 46px;
  width: 46px;
  height: 46px;
  overflow: hidden;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  background: #f9fafb;
  color: #9ca3af;
}
.inventory-product__image img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.inventory-product__info {
  min-width: 0;
}
.inventory-product__name {
  display: block;
  overflow: hidden;
  color: #111827;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.4;
  text-decoration: none;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.inventory-product__name:hover {
  text-decoration: underline;
}
.inventory-product__brand {
  display: block;
  margin-top: 3px;
  color: #9ca3af;
  font-size: 11px;
}

.inventory-sku {
  color: #6b7280;
  font-family: monospace;
  font-size: 12px;
}

.inventory-variant-count {
  color: #374151;
  font-size: 12px;
  font-weight: 600;
}

.inventory-no-variant {
  color: #9ca3af;
  font-size: 12px;
}

.inventory-stock {
  display: flex;
  align-items: center;
  gap: 8px;
}
.inventory-stock__total {
  color: #111827;
  font-size: 14px;
  font-weight: 700;
}
.inventory-stock__not-available {
  color: #9ca3af;
}
.inventory-stock__badge {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 0 7px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
}
.inventory-stock__badge--success {
  background: #ecfdf5;
  color: #047857;
}
.inventory-stock__badge--warning {
  background: #fffbeb;
  color: #b45309;
}
.inventory-stock__badge--danger {
  background: #fef2f2;
  color: #dc2626;
}

.inventory-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 600;
}
.inventory-status__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}
.inventory-status--active {
  color: #047857;
}
.inventory-status--active .inventory-status__dot {
  background: #10b981;
}
.inventory-status--inactive {
  color: #6b7280;
}
.inventory-status--inactive .inventory-status__dot {
  background: #9ca3af;
}

.inventory-icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border: 1px solid #e5e7eb;
  border-radius: 7px;
  background: #fff;
  color: #6b7280;
  font-size: 12px;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}
.inventory-icon-button:hover {
  border-color: #d1d5db;
  background: #f9fafb;
  color: #111827;
}
.inventory-icon-button--view.is-expanded i {
  transform: rotate(180deg);
}
.inventory-icon-button--view i {
  transition: transform 0.2s ease;
}

.inventory-variants-row {
  background: #f9fafb;
}
.inventory-variants-row > td {
  padding: 0 20px 16px !important;
}

.inventory-variants {
  overflow: hidden;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  background: #fff;
}
.inventory-variants__header,
.inventory-variants .inventory-variant {
  display: grid;
  grid-template-columns: minmax(180px, 2fr) minmax(120px, 1fr) 100px 120px 100px 50px;
  align-items: center;
  gap: 16px;
  padding: 11px 14px;
}
.inventory-variants__header {
  border-bottom: 1px solid #e5e7eb;
  background: #f9fafb;
  color: #6b7280;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.inventory-variants .inventory-variant {
  border-bottom: 1px solid #f0f1f3;
}
.inventory-variants .inventory-variant:last-child {
  border-bottom: 0;
}
.inventory-variants .inventory-variant__name {
  color: #111827;
  font-size: 12px;
  font-weight: 600;
}
.inventory-variants .inventory-variant__sku {
  color: #6b7280;
  font-family: monospace;
  font-size: 11px;
}
.inventory-variants .inventory-variant__price {
  color: #374151;
  font-size: 12px;
  font-weight: 600;
}
.inventory-variants .inventory-variant__stock {
  display: flex;
  align-items: center;
  gap: 7px;
}
.inventory-variants .inventory-variant__stock strong {
  color: #111827;
  font-size: 12px;
}
.inventory-variants .inventory-variant__action {
  display: flex;
  justify-content: flex-end;
}

.inventory-empty {
  display: flex;
  align-items: center;
  flex-direction: column;
  text-align: center;
}
.inventory-empty__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  margin-bottom: 14px;
  border-radius: 12px;
  background: #f3f4f6;
  color: #9ca3af;
  font-size: 20px;
}
.inventory-empty h3 {
  margin: 0;
  color: #111827;
  font-size: 15px;
  font-weight: 700;
}
.inventory-empty p {
  margin: 6px 0 18px;
  color: #6b7280;
  font-size: 12px;
}

.inventory-pagination {
  display: flex;
  justify-content: flex-end;
  padding: 16px 20px;
  border-top: 1px solid #e5e7eb;
}
.inventory-pagination nav {
  display: flex;
  align-items: center;
  gap: 4px;
}
.inventory-pagination a,
.inventory-pagination span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 32px;
  height: 32px;
  padding: 0 8px;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  color: #374151;
  font-size: 12px;
  text-decoration: none;
}
.inventory-pagination span[aria-current=page] {
  border-color: #111827;
  background: #111827;
  color: #fff;
}

@media (max-width: 1200px) {
  .inventory-stats {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .inventory-filters__form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 768px) {
  .inventory-page {
    padding: 16px;
  }
  .inventory-page__header {
    flex-direction: column;
  }
  .inventory-page__actions {
    width: 100%;
  }
  .inventory-page__action {
    flex: 1;
    justify-content: center;
  }
  .inventory-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .inventory-filters__form {
    grid-template-columns: 1fr;
  }
  .inventory-filters__buttons {
    justify-content: flex-start;
  }
  .inventory-table-card {
    border-radius: 8px;
  }
}
@media (max-width: 480px) {
  .inventory-stats {
    grid-template-columns: 1fr;
  }
  .inventory-page__actions {
    flex-direction: column;
  }
  .inventory-page__action {
    width: 100%;
  }
}
.inventory-product-edit-page {
  padding: 24px;
}
.inventory-product-edit-page__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
}
.inventory-product-edit-page__heading {
  min-width: 0;
}
.inventory-product-edit-page__breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
  color: #ddd;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
}
.inventory-product-edit-page__breadcrumb a {
  color: #555555;
  text-decoration: none;
  -webkit-transition: all 0.3s linear 0s;
  -o-transition: all 0.3s linear 0s;
  transition: all 0.3s linear 0s;
}
.inventory-product-edit-page__breadcrumb a:hover {
  color: #177245;
}
.inventory-product-edit-page__breadcrumb i {
  font-size: 14px;
}
.inventory-product-edit-page__title {
  margin: 0;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 24px;
  font-weight: 600;
  line-height: 1.3;
}
.inventory-product-edit-page__subtitle {
  margin: 6px 0 0;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  line-height: 1.6;
}
.inventory-product-edit-page__back {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 42px;
  padding: 0 16px;
  border: 1px solid #eaecf0;
  border-radius: 8px;
  background: #fff;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
  white-space: nowrap;
  -webkit-transition: all 0.3s linear 0s;
  -o-transition: all 0.3s linear 0s;
  transition: all 0.3s linear 0s;
}
.inventory-product-edit-page__back:hover {
  border-color: #177245;
  color: #177245;
}
.inventory-product-edit-page__layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  align-items: start;
  gap: 20px;
}
.inventory-product-edit-page__main, .inventory-product-edit-page__sidebar {
  display: flex;
  flex-direction: column;
  gap: 20px;
  min-width: 0;
}
.inventory-product-edit-page__card {
  overflow: hidden;
  border: 1px solid #eaecf0;
  border-radius: 12px;
  background: #fff;
}
.inventory-product-edit-page__card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px;
  border-bottom: 1px solid #eaecf0;
}
.inventory-product-edit-page__card-title {
  margin: 0;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 18px;
  font-weight: 600;
  line-height: 1.4;
}
.inventory-product-edit-page__card-description {
  margin: 4px 0 0;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  line-height: 1.5;
}
.inventory-product-edit-page__product {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px;
}
.inventory-product-edit-page__product-image {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 64px;
  width: 64px;
  height: 64px;
  overflow: hidden;
  border: 1px solid #eaecf0;
  border-radius: 10px;
  background: #F2F4F7;
  color: #ddd;
  font-size: 20px;
}
.inventory-product-edit-page__product-image img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.inventory-product-edit-page__product-content {
  min-width: 0;
}
.inventory-product-edit-page__product-content h3 {
  margin: 0 0 8px;
  overflow: hidden;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 18px;
  font-weight: 600;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.inventory-product-edit-page__product-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
}
.inventory-product-edit-page__product-meta strong {
  color: #0D2B5A;
  font-weight: 500;
}
.inventory-product-edit-page__product-meta .is-success {
  color: #198754;
}
.inventory-product-edit-page__product-meta .is-danger {
  color: #dc3545;
}
.inventory-product-edit-page__form {
  margin: 0;
}
.inventory-product-edit-page__form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
  padding: 20px;
}
.inventory-product-edit-page__field {
  min-width: 0;
}
.inventory-product-edit-page__label {
  display: block;
  margin-bottom: 8px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 500;
}
.inventory-product-edit-page__label span {
  color: #dc3545;
}
.inventory-product-edit-page__price-input {
  position: relative;
}
.inventory-product-edit-page__price-input > span {
  position: absolute;
  top: 50%;
  left: 14px;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  transform: translateY(-50%);
  pointer-events: none;
}
.inventory-product-edit-page__price-input input {
  width: 100%;
  height: 44px;
  padding: 0 14px 0 30px;
  border: 1px solid #eaecf0;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  -webkit-transition: all 0.3s linear 0s;
  -o-transition: all 0.3s linear 0s;
  transition: all 0.3s linear 0s;
}
.inventory-product-edit-page__price-input input:focus {
  border-color: #177245;
  box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.04);
}
.inventory-product-edit-page__price-input input.is-invalid {
  border-color: #dc3545;
}
.inventory-product-edit-page__current-value {
  display: flex;
  align-items: center;
  height: 44px;
  padding: 0 14px;
  border: 1px solid #eaecf0;
  border-radius: 8px;
  background: #F2F4F7;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 500;
}
.inventory-product-edit-page__error {
  margin: 6px 0 0;
  color: #dc3545;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
}
.inventory-product-edit-page__form-footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 16px 20px;
  border-top: 1px solid #eaecf0;
  background: #F2F4F7;
}
.inventory-product-edit-page__button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 42px;
  padding: 0 16px;
  border: 1px solid transparent;
  border-radius: 8px;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
  cursor: pointer;
  -webkit-transition: all 0.3s linear 0s;
  -o-transition: all 0.3s linear 0s;
  transition: all 0.3s linear 0s;
}
.inventory-product-edit-page__button:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}
.inventory-product-edit-page__button--primary {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.inventory-product-edit-page__button--primary:hover:not(:disabled) {
  background: #D4AF37;
  border-color: #D4AF37;
}
.inventory-product-edit-page__button--secondary {
  border-color: #eaecf0;
  background: #fff;
  color: #555555;
}
.inventory-product-edit-page__button--secondary:hover {
  border-color: #177245;
  color: #177245;
}
.inventory-product-edit-page__count {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 0 10px;
  border-radius: 999px;
  background: #F2F4F7;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
}
.inventory-product-edit-page__variants {
  display: flex;
  flex-direction: column;
}
.inventory-product-edit-page__variant {
  display: grid;
  grid-template-columns: minmax(180px, 1fr) 120px 100px 40px;
  align-items: center;
  gap: 18px;
  padding: 15px 20px;
  border-bottom: 1px solid #eaecf0;
}
.inventory-product-edit-page__variant:last-child {
  border-bottom: 0;
}
.inventory-product-edit-page__variant-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.inventory-product-edit-page__variant-info strong {
  overflow: hidden;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.inventory-product-edit-page__variant-info span {
  overflow: hidden;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.inventory-product-edit-page__variant-data {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.inventory-product-edit-page__variant-data span {
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
}
.inventory-product-edit-page__variant-data strong {
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
}
.inventory-product-edit-page__variant-data .is-success {
  color: #198754;
}
.inventory-product-edit-page__variant-data .is-warning {
  color: #ffc107;
}
.inventory-product-edit-page__variant-data .is-danger {
  color: #dc3545;
}
.inventory-product-edit-page__icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border: 1px solid #eaecf0;
  border-radius: 8px;
  background: #fff;
  color: #555555;
  font-size: 14px;
  text-decoration: none;
  -webkit-transition: all 0.3s linear 0s;
  -o-transition: all 0.3s linear 0s;
  transition: all 0.3s linear 0s;
}
.inventory-product-edit-page__icon-button:hover {
  border-color: #177245;
  color: #177245;
}
.inventory-product-edit-page__summary {
  display: flex;
  flex-direction: column;
}
.inventory-product-edit-page__summary-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 18px;
  border-bottom: 1px solid #eaecf0;
}
.inventory-product-edit-page__summary-item:last-child {
  border-bottom: 0;
}
.inventory-product-edit-page__summary-item span {
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
}
.inventory-product-edit-page__summary-item strong {
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
}
.inventory-product-edit-page__summary-item .is-warning {
  color: #ffc107;
}
.inventory-product-edit-page__summary-item .is-danger {
  color: #dc3545;
}
.inventory-product-edit-page__notice {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 18px;
  border: 1px solid #eaecf0;
  border-radius: 12px;
  background: #F2F4F7;
}
.inventory-product-edit-page__notice-icon {
  flex: 0 0 auto;
  color: #0dcaf0;
  font-size: 18px;
}
.inventory-product-edit-page__notice h3 {
  margin: 0 0 6px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 16px;
  font-weight: 600;
}
.inventory-product-edit-page__notice p {
  margin: 0;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  line-height: 1.6;
}
@media (min-width: 992px) and (max-width: 1199px) {
  .inventory-product-edit-page__layout {
    grid-template-columns: minmax(0, 1fr);
  }
  .inventory-product-edit-page__sidebar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (min-width: 768px) and (max-width: 991px) {
  .inventory-product-edit-page {
    padding: 20px;
  }
  .inventory-product-edit-page__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .inventory-product-edit-page__form-grid {
    grid-template-columns: 1fr;
  }
  .inventory-product-edit-page__variant {
    grid-template-columns: minmax(180px, 1fr) 100px 90px 40px;
    gap: 12px;
  }
